// codex.rs:2306 每次 run_turn() 都调用
pub(crate) async fn build_initial_context(
  &self,
  turn_context: &TurnContext,
) -> Vec<ResponseItem> {
  let mut developer_sections = Vec::with_capacity(8);
  let mut contextual_user_sections = Vec::with_capacity(2);
  ..

// codex.rs:544 — 三级优先级
let base_instructions = config.base_instructions
  .clone()
  // ① 用户显式覆盖
  .or_else(|| conversation_history
    .get_base_instructions()
    .map(|s| s.text))
  // ② 历史会话保存的 base_instructions
  .unwrap_or_else(||
    model_info.get_model_instructions(config.personality)
  );
  // ③ models-manager/prompt.md (默认)

// codex.rs:2339 — 权限指令注入
if config.include_permissions_instructions {
  developer_sections.push(
    DeveloperInstructions::from_policy(
      sandbox_policy,   // e.g. WorkspaceWrite
      approval_policy,  // e.g. UnlessTrusted
      approvals_reviewer,
      exec_policy.current().as_ref(),
      &turn_context.cwd,
      features.enabled(Feature::ExecPermissionApprovals),
      features.enabled(Feature::RequestPermissionsTool),  // ← 第7个参数
    ).into_text(),
  );
}

// codex.rs:2359 — AGENTS.md + developer 指令
if !separate_guardian_developer_message
  && let Some(instr) = turn_context
    .developer_instructions.as_deref()
  && !instr.is_empty()
{
  developer_sections.push(instr.to_string());
}
// 来源：
// - AGENTS.md 文件内容（多级查找）
// - CLI --developer-instructions 参数
// - app-server 客户端注入

// codex.rs:2417 — Skills 注入
let implicit_skills = turn_context
  .turn_skills
  .outcome
  .allowed_skills_for_implicit_invocation();

if let Some(skills_section) =
  render_skills_section(&implicit_skills)
{
  developer_sections.push(skills_section);
}
// render_skills_section() 输出:
// <skills_instructions>
//   ## Skills
//   - skill_name: description (file: path)
//   ### How to use skills
//   ...
// </skills_instructions>

// codex.rs:2440 — user 侧上下文
if let Some(user_instructions) =
  turn_context.user_instructions.as_deref()
{
  contextual_user_sections.push(
    UserInstructions { text: .., directory: .. }
      .serialize_to_text(),
  );
}
if config.include_environment_context {
  contextual_user_sections.push(
    EnvironmentContext::from_turn_context(turn_context, shell)
      .serialize_to_xml(),
  );
  // 输出示例：
  // <environment_context>
  //   <cwd>/home/user/myproject</cwd>
  //   <shell>zsh</shell>
  //   <current_date>2026-05-28</current_date>
  //   <timezone>Asia/Shanghai</timezone>
  // </environment_context>
}

// codex.rs:2462 — 合并为 ResponseItem[]
let mut items = Vec::with_capacity(3);

// 所有 developer_sections → 一条 DeveloperMessage
if let Some(dev_msg) =
  build_developer_update_item(developer_sections)
{
  items.push(dev_msg);
}

// 所有 user_sections → 一条 UserMessage
if let Some(user_msg) =
  build_contextual_user_message(contextual_user_sections)
{
  items.push(user_msg);
}

items  // → Vec<ResponseItem> (2~3条)
